/**
 * 产品介绍大图轮播（1600×900）
 * 层叠淡入淡出 + 定时轮询；指针悬停 / 触摸 / 用户暂停 / 系统减少动态效果时停止
 * @author 恒哥
 *
 * 🔴 WCAG 2.2.2（2026-11-27）：自动轮播必须可暂停、可隐藏、可暂停于交互。
 *    - 常驻「暂停 / 播放」按钮，aria-pressed 表达状态。
 *    - prefers-reduced-motion: reduce 时**不自动播放**（系统偏好优先）。
 *    - SSR 安全：matchMedia 只在 useEffect 里读（服务端无 window），初值恒 false。
 *    - Safari <14 无 addEventListener，回退 addListener / removeListener。
 *    - 进度条与计时器共用同一个 `isPaused` 来源（原实现 ref + DOM 直改两份状态，
 *      暂停后进度条与计时器会错步）——改为 CSS animation + React state 单一驱动。
 */
import React, { useEffect, useRef, useState } from 'react';
import { useI18n } from '../../i18n';
import './product-card-gallery.css';

/**
 * @param {object} props
 * @param {Array<{id:string,src:string,title:string,caption?:string}>} props.cards
 * @param {string} [props.className]
 * @param {number} [props.initialIndex]
 * @param {boolean} [props.autoPlay]
 * @param {number} [props.intervalMs]
 */
export default function ProductCardGallery({
  cards = [],
  className = '',
  initialIndex = 0,
  autoPlay = true,
  intervalMs = 4000,
}) {
  const count = cards.length;
  const { t } = useI18n();
  const a11y = t.a11y || {};
  const [active, setActive] = useState(() =>
    Math.min(Math.max(initialIndex, 0), Math.max(count - 1, 0))
  );
  // 三个暂停来源都进 state，合成单一 isPaused；不再用 ref + DOM 直改。
  const [userPaused, setUserPaused] = useState(false);
  const [hoverPaused, setHoverPaused] = useState(false);
  // 🔴 SSR 安全：初值恒 false，浏览器偏好在挂载后由 useEffect 同步。
  const [reducedMotion, setReducedMotion] = useState(false);
  const touchStartX = useRef(null);

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return undefined;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => setReducedMotion(Boolean(mq.matches));
    sync();
    // Safari <14 回退：addEventListener 不存在时用 addListener。
    if (typeof mq.addEventListener === 'function') {
      mq.addEventListener('change', sync);
      return () => mq.removeEventListener('change', sync);
    }
    mq.addListener(sync);
    return () => mq.removeListener(sync);
  }, []);

  const isPaused = userPaused || hoverPaused || reducedMotion;
  const shouldAutoPlay = autoPlay && count > 1 && !isPaused;

  useEffect(() => {
    if (!shouldAutoPlay) return undefined;
    const timer = window.setInterval(() => {
      setActive((prev) => (prev + 1) % count);
    }, intervalMs);
    return () => window.clearInterval(timer);
  }, [shouldAutoPlay, count, intervalMs]);

  if (!count) return null;

  const current = cards[active] || cards[0];

  const goTo = (index) => setActive(((index % count) + count) % count);
  const goNext = () => goTo(active + 1);
  const goPrev = () => goTo(active - 1);

  return (
    <div className={`product-card-gallery ${className}`.trim()}>
      <div
        className="product-card-gallery-frame"
        onMouseEnter={() => setHoverPaused(true)}
        onMouseLeave={() => setHoverPaused(false)}
        onTouchStart={(e) => {
          touchStartX.current = e.changedTouches[0]?.clientX ?? null;
          setHoverPaused(true);
        }}
        onTouchEnd={(e) => {
          setHoverPaused(false);
          if (touchStartX.current == null) return;
          const dx = (e.changedTouches[0]?.clientX ?? 0) - touchStartX.current;
          touchStartX.current = null;
          if (Math.abs(dx) < 40) return;
          if (dx < 0) goNext();
          else goPrev();
        }}
      >
        {cards.map((card, index) => (
          <picture key={card.base}>
            <source type="image/avif" srcSet={card.avif} sizes="(max-width: 1024px) calc(100vw - 2.5rem), 960px" />
            <img
              className={`product-card-gallery-img${index === active ? ' is-active' : ''}`}
              src={card.fallback}
              alt={card.title}
              width={1600}
              height={900}
              loading={index === 0 ? 'eager' : 'lazy'}
              decoding="async"
              draggable={false}
            />
          </picture>
        ))}

        {count > 1 && (
          <>
            {/* 进度条：CSS animation 驱动，key=active 使每张片重新计时；
                animationPlayState 与计时器共用同一个 isPaused，不再错步。
                reducedMotion 时整个进度条不渲染（既不自动播放也不误导）。 */}
            {autoPlay && !reducedMotion && (
              <div className="product-card-gallery-progress" aria-hidden="true">
                <span
                  key={active}
                  className="product-card-gallery-progress-bar"
                  style={{
                    animationDuration: `${intervalMs}ms`,
                    animationPlayState: isPaused ? 'paused' : 'running',
                  }}
                />
              </div>
            )}
            {/* 🔴 WCAG 2.2.2：常驻暂停/播放按钮。reducedMotion 时自动播放已被禁用，
                按钮此时的唯一作用是允许主动开启——但 shouldAutoPlay 仍为 false，
                故直接不渲染，避免“点了没反应”的假交互。 */}
            {autoPlay && !reducedMotion && (
              <button
                type="button"
                className="product-card-gallery-toggle"
                aria-label={userPaused
                  ? (a11y.playSlideshow || 'Play slideshow')
                  : (a11y.pauseSlideshow || 'Pause slideshow')}
                aria-pressed={userPaused}
                onClick={() => setUserPaused((v) => !v)}
              >
                {userPaused ? '▶' : '❚❚'}
              </button>
            )}
            <button
              type="button"
              className="product-card-gallery-nav product-card-gallery-nav-prev"
              aria-label={a11y.previousSlide || 'Previous slide'}
              onClick={goPrev}
            >
              ‹
            </button>
            <button
              type="button"
              className="product-card-gallery-nav product-card-gallery-nav-next"
              aria-label={a11y.nextSlide || 'Next slide'}
              onClick={goNext}
            >
              ›
            </button>
            <div className="product-card-gallery-dots" role="tablist" aria-label="Slides">
              {cards.map((card, index) => (
                <button
                  key={card.id}
                  type="button"
                  role="tab"
                  aria-selected={index === active}
                  aria-label={card.title}
                  className={`product-card-gallery-dot${index === active ? ' is-active' : ''}`}
                  onClick={() => goTo(index)}
                />
              ))}
            </div>
            {/* 自动播放时不播报，避免屏幕阅读器每 4 秒被打断；暂停后恢复播报。 */}
            <span
              className="product-card-gallery-live"
              aria-live={shouldAutoPlay ? 'off' : 'polite'}
            >
              {active + 1} / {count}
            </span>
          </>
        )}
      </div>

      <p className="product-card-gallery-caption">
        <strong>{current.title}</strong>
        {current.caption ? ` — ${current.caption}` : ''}
      </p>

      {count > 1 && (
        <div className="product-card-gallery-tabs" role="tablist" aria-label="Product overview cards">
          {cards.map((card, index) => (
            <button
              key={card.id}
              type="button"
              role="tab"
              aria-selected={index === active}
              className={`product-card-gallery-tab${index === active ? ' is-active' : ''}`}
              onClick={() => goTo(index)}
            >
              {card.title}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
